/// A widget in the system.
pub struct Widget { pub id: u64, pub name: String }

/// Does operation 0 on the widget store.
pub fn operation_0(store: &mut HashMap<u64, Widget>, id: u64) -> Option<String> {
    let w = store.get(&id)?;
    let label = format!("op0:{}", w.name);
    Some(label)
}

